import 'dart:convert';
import 'dart:io';
import '../models/deck_model.dart';

class DeckFlutterWebExporter {
  /// Generates a standalone, production-ready Flutter Web application project structure
  /// that renders the entire deck with 60fps animations, keyboard navigation,
  /// fullscreen support, and responsive 16:9 canvas.
  static Future<File> exportProjectToFlutterWeb({
    required PortfolioProject project,
    required String outputDartPath,
  }) async {
    final buffer = StringBuffer();

    buffer.writeln('''// AUTO-GENERATED FLUTTER WEB PRESENTATION ENGINE
// Generated by DeckStudio for: ${project.title}
// Author: ${project.author}

import 'package:flutter/material.dart';
import 'package:flutter/services.dart';

void main() {
  runApp(const DeckPresentationWebApp());
}

class DeckPresentationWebApp extends StatelessWidget {
  const DeckPresentationWebApp({super.key});

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      title: '${project.title}',
      debugShowCheckedModeBanner: false,
      theme: ThemeData(
        fontFamily: 'Pretendard',
        scaffoldBackgroundColor: const Color(0xFF0B0F17),
      ),
      home: const FullscreenDeckViewer(),
    );
  }
}

class FullscreenDeckViewer extends StatefulWidget {
  const FullscreenDeckViewer({super.key});

  @override
  State<FullscreenDeckViewer> createState() => _FullscreenDeckViewerState();
}

class _FullscreenDeckViewerState extends State<FullscreenDeckViewer> {
  int _currentIndex = 0;
  final FocusNode _focusNode = FocusNode();

  final List<Map<String, dynamic>> _slides = [''');

    for (int i = 0; i < project.slides.length; i++) {
      final s = project.slides[i];
      String? imgPath;
      for (final e in s.elements) {
        final p = e.props['imagePath'] as String?;
        if (p != null && p.contains('slide_')) {
          imgPath = p.replaceAll('\\', '/');
          break;
        }
      }

      buffer.writeln('''    {
      'page': ${s.pageNumber},
      'title': '${s.title.replaceAll("'", "\\'")}',
      'imagePath': ${imgPath != null ? "'$imgPath'" : "null"},
      'bgColor': 0x${s.backgroundColor.toARGB32().toRadixString(16)},
    },''');
    }

    buffer.writeln('''  ];

  @override
  void initState() {
    super.initState();
    WidgetsBinding.instance.addPostFrameCallback((_) {
      _focusNode.requestFocus();
    });
  }

  void _next() {
    if (_currentIndex < _slides.length - 1) {
      setState(() => _currentIndex++);
    }
  }

  void _prev() {
    if (_currentIndex > 0) {
      setState(() => _currentIndex--);
    }
  }

  @override
  Widget build(BuildContext context) {
    final slide = _slides[_currentIndex];

    return Scaffold(
      backgroundColor: const Color(0xFF0B0F17),
      body: KeyboardListener(
        focusNode: _focusNode,
        autofocus: true,
        onKeyEvent: (event) {
          if (event is KeyDownEvent) {
            if (event.logicalKey == LogicalKeyboardKey.arrowRight ||
                event.logicalKey == LogicalKeyboardKey.space ||
                event.logicalKey == LogicalKeyboardKey.pageDown) {
              _next();
            } else if (event.logicalKey == LogicalKeyboardKey.arrowLeft ||
                event.logicalKey == LogicalKeyboardKey.pageUp) {
              _prev();
            }
          }
        },
        child: Stack(
          children: [
            // Centered 16:9 Presentation Canvas
            Center(
              child: AspectRatio(
                aspectRatio: 16 / 9,
                child: Container(
                  decoration: BoxDecoration(
                    color: Color(slide['bgColor'] as int),
                    boxShadow: const [
                      BoxShadow(
                        color: Colors.black54,
                        blurRadius: 40,
                        offset: Offset(0, 10),
                      ),
                    ],
                  ),
                  child: slide['imagePath'] != null
                      ? Image.network(
                          slide['imagePath'] as String,
                          fit: BoxFit.fill,
                          errorBuilder: (_, __, ___) => _buildVectorFallback(slide),
                        )
                      : _buildVectorFallback(slide),
                ),
              ),
            ),

            // Floating Navigation Controller
            Positioned(
              bottom: 24,
              left: 0,
              right: 0,
              child: Center(
                child: Container(
                  padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 8),
                  decoration: BoxDecoration(
                    color: const Color(0xDD0F172A),
                    borderRadius: BorderRadius.circular(30),
                    border: Border.all(color: Colors.white12),
                  ),
                  child: Row(
                    mainAxisSize: MainAxisSize.min,
                    children: [
                      IconButton(
                        icon: const Icon(Icons.arrow_back_ios_new, color: Colors.white, size: 16),
                        onPressed: _prev,
                        tooltip: '이전 슬라이드 (←)',
                      ),
                      const SizedBox(width: 8),
                      Text(
                        '\${_currentIndex + 1} / \${_slides.length}',
                        style: const TextStyle(
                          color: Colors.white,
                          fontSize: 13,
                          fontWeight: FontWeight.bold,
                        ),
                      ),
                      const SizedBox(width: 8),
                      IconButton(
                        icon: const Icon(Icons.arrow_forward_ios, color: Colors.white, size: 16),
                        onPressed: _next,
                        tooltip: '다음 슬라이드 (→)',
                      ),
                    ],
                  ),
                ),
              ),
            ),
          ],
        ),
      ),
    );
  }

  Widget _buildVectorFallback(Map<String, dynamic> slide) {
    return Center(
      child: Column(
        mainAxisSize: MainAxisSize.min,
        children: [
          Text(
            'Slide \${slide['page']}',
            style: const TextStyle(color: Color(0xFF0052FF), fontSize: 18, fontWeight: FontWeight.bold),
          ),
          const SizedBox(height: 12),
          Text(
            slide['title'].toString(),
            style: const TextStyle(color: Color(0xFF0F172A), fontSize: 28, fontWeight: FontWeight.bold),
          ),
        ],
      ),
    );
  }
}
''');

    final file = File(outputDartPath);
    await file.writeAsString(buffer.toString(), encoding: utf8);
    return file;
  }
}

